/* game_host.h -- a JavaScript-like host's adapter over the Botlish native
 * library game, generated by hostgen host-module. Do not edit. */
#ifndef game_HOST_H
#define game_HOST_H

#include <stdbool.h>
#include <stddef.h>

typedef enum { HV_UNDEFINED = 0, HV_NUMBER, HV_BOOLEAN, HV_STRING } hv_kind;

/* A host value: a number (a double, as JavaScript's), a boolean, a
 * string (UTF-8 bytes) or undefined. */
typedef struct {
    hv_kind kind;
    double number;
    bool boolean;
    const char *text;
    size_t length;
} hv_value;

/* A call's outcome: its value, or its error (the host's error class:
 * TypeError, RangeError or BotlishError; the code and the message). A
 * string value's bytes are owned by the result until it is released. */
typedef struct {
    bool failed;
    char error[16];
    char code[128];
    char message[512];
    hv_value value;
    char *storage;
} hv_result;

typedef struct game_host game_host;

/* Opens the library's instance (one per host thread); 0 or -1 with MESSAGE. */
int game_host_open(game_host **host, char *message, size_t size);
void game_host_close(game_host *host);
/* Calls METHOD (a Spec method's name) with ARGS. */
void game_host_call(game_host *host, const char *method, const hv_value *args, size_t count, hv_result *result);
void game_host_result_release(hv_result *result);

#endif
